import { resolve } from "node:path";
import { readFile, writeFile } from "node:fs/promises";
const result = await Bun.build({
  entrypoints: [resolve(import.meta.dir, "lint-entry.ts")],
  target: "node",
  format: "esm",
  minify: { whitespace: true, syntax: false, identifiers: false },
});
if (!result.success) throw new AggregateError(result.logs, "Could not build the design linter");
const destination = resolve(import.meta.dir, "../lint.gen.mjs");
const generated =
  "// Code generated by scripts/build-lint.ts from local linter sources. DO NOT EDIT.\n" +
  (await result.outputs[0]!.text()).trimEnd() +
  "\n";
if (process.argv.includes("--check")) {
  if ((await readFile(destination, "utf8")) !== generated)
    throw new Error("Run go generate ./extensions/open-design to refresh the embedded linter.");
} else {
  await writeFile(destination, generated);
}
